uint8_t* lframes[] = {lframe0, lframe1, lframe2, lframe3, lframe4, lframe5, lframe6, lframe7, lframe8, lframe9, lframe10, lframe11, lframe12, lframe13, lframe14, lframe15};
uint8_t rframes[16][1024] = {0};
uint8_t activeFrame[1024];

void merge_frames(int lframe, int rframe) {
  for (int i = 0; i < 1023; i++) {
    if (rframes[rframe][i] != 0)
      activeFrame[i] = rframes[rframe][i];
    else if (lframes[lframe][i] != 0)
      activeFrame[i] = lframes[lframe][i];
    else
      activeFrame[i] = 0;
  }
}

void generate_rframes(int bytes_shift) {
  for (int i = 0; i < 16; i++) {
    for (int j = 0; j < 1024; j++) {
      rframes[i][j+bytes_shift] = lframes[i][j];
    }
  }
} 



std::atomic<float> leftSet{};
std::atomic<float> rightSet{};

// callback, runs when board A sends data to board B.
void receiveDataCB(const uint8_t* mac, const uint8_t* incomingData, int len) 
{ 
  struct AtoBPacket received_data{};
  memcpy(&received_data, incomingData, sizeof(received_data));

  // ping pong
  (void*)esp_now_send(A_MAC, (uint8_t *)&received_data, sizeof(received_data));
  
  leftSet = received_data.setLeftAngvel;
  rightSet = received_data.setRightAngvel;
  
}

void setup() {

  generate_rframes(7);
  if (1)
    Serial.begin(115200);

  // display
  Wire.begin(SDA, SCL);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3c)) {
    Serial.println(F("SSD1306 allocation failed"));
    for (;;);
  }
  display.setRotation(0);
  display.clearDisplay();
  display.display();

  // espnow
  WiFi.mode(WIFI_STA);
  WiFi.setSleep(false);
  esp_wifi_set_channel(11, WIFI_SECOND_CHAN_NONE);
  esp_wifi_set_max_tx_power(84);
  esp_now_init();
  memcpy(peerInfo.peer_addr, A_MAC, 6);
  peerInfo.channel = 0;  
  //peerInfo.encrypt = true;
  //esp_now_set_pmk((uint8_t*)PMK);
  //for (uint8_t i = 0; i < 16; i++) peerInfo.lmk[i] = LMK[i];
  esp_now_add_peer(&peerInfo);
  esp_now_register_recv_cb(esp_now_recv_cb_t(receiveDataCB));
}

void loop() {
  static float leftWheelPosition = 0; // 0-6.28, wraps around
  static float rightWheelPosition = 0; // 0-6.28, wraps around
  static uint8_t leftFrameIdx = 0;
  static uint8_t rightFrameIdx = 0;
  static unsigned long lastDrawMs = 0;
  static unsigned long lastMotorUpdateMs = 0;
  static unsigned long wheelUpdatePeriodMs = 10;
  static unsigned long drawPeriodMs = 1;

  // main drawing
  if (1 || millis() - lastDrawMs >= drawPeriodMs) {
    display.clearDisplay();
    merge_frames(leftFrameIdx, rightFrameIdx);
    display.drawBitmap(0, 0, activeFrame, 128, 64, SSD1306_WHITE);
    display.display();
    lastDrawMs = millis();
  }


  // track motors based on velocity received

  if (millis() - lastMotorUpdateMs > wheelUpdatePeriodMs) {
    float dt = (float)(millis() - lastMotorUpdateMs) / 1000;
    //Serial.printf("%.4f %.2f %.2f %d %d\n", dt, leftWheelPosition, rightWheelPosition, leftFrameIdx, rightFrameIdx);

    // left
    leftWheelPosition += leftSet * dt;
    if (leftWheelPosition > 6.28)
      leftWheelPosition = 0.0;
    if (leftWheelPosition < 0.0)
      leftWheelPosition = 6.28;
    
    leftFrameIdx = (uint8_t)floor(15.8 * leftWheelPosition / 6.28);

    // right
    rightWheelPosition += rightSet * dt;
    if (rightWheelPosition > 6.28)
      rightWheelPosition = 0.0;
    if (rightWheelPosition < 0.0)
      rightWheelPosition = 6.28;

    rightFrameIdx = (uint8_t)floor(15.8 * rightWheelPosition / 6.28);

    lastMotorUpdateMs = millis();
  }
}



